import { createContext, useContext } from "react";
import { useStore } from "zustand";
import { createStore } from "zustand/vanilla";
import { assertNotNull } from "../assert";
export function createGraphRenderingStore(expandedSubtrees) {
    return createStore()((set) => ({
        expandedNodes: {},
        expandedSubtrees,
        toggleExpandedNode: (nodeId) => set((state) => ({
            expandedNodes: {
                ...state.expandedNodes,
                [nodeId]: !state.expandedNodes[nodeId],
            },
        })),
        toggleExpandedSubtree: (nodeId) => set((state) => ({
            expandedSubtrees: {
                ...state.expandedSubtrees,
                [nodeId]: !state.expandedSubtrees[nodeId],
            },
        })),
    }));
}
export const GraphRenderingStoreContext = createContext(null);
export function useGraphRenderingStore(selector) {
    const store = useContext(GraphRenderingStoreContext);
    assertNotNull(store);
    return useStore(store, selector);
}
