    display: flex;
    flex-direction: column;
    border: 1px solid transparent;
    border-radius: .8em;
    padding: .3em .5em;
    transition-property: border-color, background-color;
    transition-duration: 0.2s;

    & > .qg-graph-node-head,
    & > .qg-color-bar {
        flex: none;
    }

    & > .qg-graph-node-body-wrapper {
        flex: 1 1 auto;
        min-height: 0;
    }

    &.qg-no-props {
        cursor: default;
    }

    &.qg-collapsed:hover,
    &.qg-expanded,
    &.qg-resizing {
        cursor: pointer;
        background: white;
        border-color: hsl(0,0%, 80%);
        box-shadow: 1px 2px 5px hsl(0,0%,90%);
    }
}

.qg-graph-node.qg-resizing {
    box-sizing: border-box;
    overflow: hidden;
}

.query-graph .qg-subtree-toggle {
    position: absolute;
    left: 50%;
    width: .7em;
    height: .7em;
    bottom: 0;
    padding: 0;
    transform: translate(-50%, 50%);
    border: 0;
    background: none;
    color: inherit;
    font: inherit;
    cursor: pointer;

    &.qg-collapsed {
        opacity: 0;
    }

    &:focus-visible {
        opacity: 1;
    }

    &:hover .qg-subtree-handle-background {
        fill: hsl(0,0%,70%);
    }
}

.qg-subtree-handle-icon {
    display: block;
    width: 100%;
    height: 100%;
    overflow: visible;

    & .qg-subtree-handle-background {
        fill: hsl(0,0%,85%);
        stroke: var(--xy-handle-border-color, var(--xy-handle-border-color-default));
        stroke-width: 1.5;
        transition: fill 0.2s;
    }

    & path {
        fill: none;
        stroke: currentColor;
        stroke-width: 1.75;
        stroke-linecap: round;
    }

    & .qg-subtree-handle-vertical {
        transition: opacity 0.12s ease;

        .qg-subtree-toggle.qg-expanded & {
            opacity: 0;
        }
    }
}

.query-graph .react-flow__node-querynode:hover .qg-subtree-toggle {
    opacity: 1;
}

.qg-graph-node-head {
    width: max-content;
    margin: auto;
    text-align: center;
}

/* A bar drawn above and/or below the node.
 * Several colors are split into equal segments. */
.qg-color-bar {
    display: flex;
    gap: 1px;
    width: 2.4em;
    height: 4px;
    margin-left: auto;
    margin-right: auto;
}
.qg-color-bar-above {
    margin-bottom: 4px;
}
.qg-color-bar-below {
    margin-top: 4px;
}
.qg-color-bar-seg {
    flex: 1 1 0;
    border-radius: 2px;
}

.qg-graph-node-label {
    /*
     * Clip the label at some length; long labels can become quite unreadable
     */
    max-width: 10em;
    text-overflow: ellipsis;
    overflow: hidden;
    /*
     * We set up everything such that we can draw a nice background for the label.
     * If the node label should be highlighted, a \`background-color\` is set from React.
     */
    border-radius: .4em;
    padding: 0 .15em;
}

.qg-graph-node-body-wrapper {
    max-width: 0;
    max-height: 0;
    overflow: hidden;

    .qg-graph-node.qg-expanded &,
    .qg-graph-node.qg-resizing & {
        max-width: 30em;
        max-height: 20em;
    }
}
.qg-graph-node-body {
    width: max-content;
    height: max-content;
    overflow: auto;
    max-width: 30em;
    max-height: 20em;

    .qg-graph-node.qg-expanded &,
    .qg-graph-node.qg-resizing & {
        padding-bottom: 0.6em;
    }
}

.qg-prop-name {
    color: hsl(0, 0%, 50%);
    -webkit-user-select: none;
    -ms-user-select: none;
    user-select: none;
}

.qg-prop-value {
    -webkit-user-select: text;
    -ms-user-select: text;
    user-select: text;
}
