___CSS_LOADER_EXPORT___.push([module.id, `.qg-collapsible-panel {
    box-sizing: border-box;
    /*
     * Together with the summary/content z-index rules below, keep body widgets in a
     * panel-local stacking order. In particular, CodeMirror's z-index: 200 gutter
     * remains inside the body's z-index: 0 context, allowing the summary's z-index: 1
     * focus outline to paint above it.
     */
    isolation: isolate;
    /* Match the card treatment used by hovered and expanded graph nodes. */
    background: white;
    border: 1px solid hsl(0, 0%, 85%);
    border-radius: 8px;
    box-shadow:
        0 2px 6px hsl(0, 0%, 0%, 0.08),
        0 1px 2px hsl(0, 0%, 0%, 0.06);

    & > summary {
        /* Paint the interactive header above any high-z-index body widgets. */
        position: relative;
        z-index: 1;

        /* Lay out the header contents in a row. */
        display: flex;
        align-items: center;
        gap: 0.4em;
        padding: 0.5em;
        font-weight: 600;
        list-style: none;
        user-select: none;
        cursor: pointer;

        &:focus-visible {
            outline: 2px solid hsl(210, 90%, 65%);
            outline-offset: 2px;
            border-radius: 8px;
        }

        /* Replace the browser marker with the consistently styled chevron below. */
        &::-webkit-details-marker {
            display: none;
        }

        & .qg-collapsible-panel-chevron {
            width: 1em;
            height: 1em;
            flex: 0 0 auto;
            fill: none;
            stroke: currentColor;
            stroke-width: 1.75;
            stroke-linecap: round;
            stroke-linejoin: round;
            transform-origin: center;
            transition: transform 0.12s ease;
        }
    }

    &[open] > summary .qg-collapsible-panel-chevron {
        transform: rotate(90deg);
    }

    /* Use red to distinguish panels that need attention. */
    &.qg-highlighted {
        border-color: hsl(0, 72%, 55%);
        box-shadow:
            0 2px 6px hsl(0, 72%, 45%, 0.12),
            0 1px 2px hsl(0, 72%, 45%, 0.1);

        & > summary {
            color: hsl(0, 72%, 40%);
            background: hsl(0, 75%, 97%);
            /* Follow the inside edge of the root's 8px radius and 1px border. */
            border-radius: 7px;
        }
    }
}

.qg-attention-needed-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.25em;
    height: 1.25em;
    border-radius: 50%;
    color: white;
    background: hsl(0, 72%, 45%);
    font-size: 0.85em;
    font-weight: bold;
}

.qg-collapsible-panel-actions {
    display: flex;
    gap: 0.4em;
    margin-left: auto;
}

.qg-collapsible-panel-content {
    /* Establish the lower half of the panel-local stacking order described above. */
    position: relative;
    z-index: 0;
    /* Constrain the body and separate it visually from the header. */
    max-height: 70vh;
    overflow: auto;
    padding: 0.75em;
    border-top: 1px solid hsl(0, 0%, 90%);
}
