___CSS_LOADER_EXPORT___.push([module.id, `.query-graph {
  & .react-flow__pane {
    background: #fdfdfd;
  }

  & .react-flow__handle {
    background-color: transparent;
    border: none;
    pointer-events: none;
  }

  & .react-flow__pane,
  & .react-flow__edge,
  & .react-flow__node {
    cursor: default;
  }

  & .react-flow__edge-textbg {
    opacity: .7;
    fill: white;
    stroke: #777;
  }

  & .react-flow__edge-text {
    font-size: .6em;
  }

  & .react-flow__edge.qg-label-highlighted .react-flow__edge-text {
    fill: hsl(309, 84%, 36%);
  }

  & .react-flow__edge.qg-crosslink {
    & .react-flow__edge-path {
      stroke: #ccc;
      stroke-dasharray: 4 4;
      transition-property: stroke, stroke-width, stroke-dasharray;
      transition-duration: .5s;
    }

    &:hover .react-flow__edge-path,
    &:focus .react-flow__edge-path {
      stroke: hsl(309, 84%, 36%);
      stroke-width: 1.5px;
      stroke-dasharray: 6 2;
    }
  }
}
